contracts/core/AssetRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./AssetTokenFactory.sol";

/**
 * @title AssetRegistry
 * @notice Central registry for registering physical assets and triggering their tokenization.
 */
contract AssetRegistry is AccessControl, Pausable {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    enum AssetStatus { Pending, UnderReview, Approved, Rejected, Tokenized }

    struct Asset {
        uint256 id;
        address owner;
        string metadataCID;
        string assetType;
        uint256 valuation;
        uint256 tokenSupply;
        address tokenContract;
        AssetStatus status;
        uint256 createdAt;
        uint256 verifiedAt;
    }

    mapping(uint256 => Asset) public assets;
    uint256 public assetCount;
    mapping(address => uint256[]) public ownerAssets;

    AssetTokenFactory public immutable factory;

    event AssetRegistered(uint256 indexed assetId, address indexed owner, string metadataCID);
    event AssetStatusChanged(uint256 indexed assetId, AssetStatus oldStatus, AssetStatus newStatus);
    event AssetTokenized(uint256 indexed assetId, address tokenContract);

    constructor(address admin, address factoryAddress) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        factory = AssetTokenFactory(factoryAddress);
    }

    function registerAsset(
        string calldata metadataCID,
        string calldata assetType,
        uint256 valuation,
        uint256 tokenSupply
    ) external whenNotPaused returns (uint256) {
        require(valuation > 0, "Valuation must be positive");
        require(tokenSupply > 0, "Token supply must be positive");

        assetCount++;
        uint256 newId = assetCount;

        assets[newId] = Asset({
            id: newId,
            owner: msg.sender,
            metadataCID: metadataCID,
            assetType: assetType,
            valuation: valuation,
            tokenSupply: tokenSupply,
            tokenContract: address(0),
            status: AssetStatus.Pending,
            createdAt: block.timestamp,
            verifiedAt: 0
        });

        ownerAssets[msg.sender].push(newId);
        emit AssetRegistered(newId, msg.sender, metadataCID);
        return newId;
    }

    function updateAssetStatus(uint256 assetId, AssetStatus newStatus) external onlyRole(ADMIN_ROLE) {
        require(assetId > 0 && assetId <= assetCount, "Asset does not exist");
        AssetStatus oldStatus = assets[assetId].status;
        assets[assetId].status = newStatus;

        if (newStatus == AssetStatus.Approved) {
            assets[assetId].verifiedAt = block.timestamp;
        }

        emit AssetStatusChanged(assetId, oldStatus, newStatus);
    }

    function tokenizeAsset(uint256 assetId, string calldata name, string calldata symbol)
        external
        onlyRole(ADMIN_ROLE)
        returns (address)
    {
        require(assetId > 0 && assetId <= assetCount, "Asset does not exist");
        Asset storage asset = assets[assetId];
        require(asset.status == AssetStatus.Approved, "Asset must be approved before tokenization");

        address tokenAddress = factory.deployToken(
            assetId,
            name,
            symbol,
            asset.tokenSupply,
            asset.owner
        );

        asset.tokenContract = tokenAddress;
        asset.status = AssetStatus.Tokenized;

        emit AssetTokenized(assetId, tokenAddress);
        return tokenAddress;
    }

    function getAsset(uint256 assetId) external view returns (Asset memory) {
        return assets[assetId];
    }
}

contracts/core/AssetToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title AssetToken
 * @notice ERC20 token representing fractional ownership of a tokenized asset.
 */
contract AssetToken is ERC20, ERC20Burnable, AccessControl, Pausable {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    uint256 public immutable assetId;
    address public immutable assetOwner;
    bool public transfersRestricted;
    mapping(address => bool) public whitelist;

    event WhitelistUpdated(address indexed account, bool status);
    event TransferRestrictionChanged(bool restricted);

    constructor(
        string memory name,
        string memory symbol,
        uint256 totalSupply,
        uint256 _assetId,
        address _assetOwner,
        address admin
    ) ERC20(name, symbol) {
        assetId = _assetId;
        assetOwner = _assetOwner;
        transfersRestricted = true;

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        _grantRole(MINTER_ROLE, msg.sender);

        _mint(msg.sender, totalSupply);
    }

    function setWhitelist(address account, bool status) external onlyRole(ADMIN_ROLE) {
        whitelist[account] = status;
        emit WhitelistUpdated(account, status);
    }

    function setTransferRestriction(bool restricted) external onlyRole(ADMIN_ROLE) {
        transfersRestricted = restricted;
        emit TransferRestrictionChanged(restricted);
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function _update(address from, address to, uint256 value) internal override whenNotPaused {
        if (transfersRestricted && from != address(0) && to != address(0)) {
            require(whitelist[from] || whitelist[to] || hasRole(ADMIN_ROLE, from), "KYC Whitelist restriction");
        }
        super._update(from, to, value);
    }
}

contracts/core/AssetTokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "./AssetToken.sol";

/**
 * @title AssetTokenFactory
 * @notice Factory contract that deploys new AssetToken ERC20 contracts for registered assets.
 */
contract AssetTokenFactory is AccessControl {
    bytes32 public constant DEPLOYER_ROLE = keccak256("DEPLOYER_ROLE");

    mapping(uint256 => address) public assetTokens;
    address[] public allTokens;

    event TokenDeployed(
        uint256 indexed assetId,
        address indexed tokenAddress,
        string name,
        string symbol,
        uint256 totalSupply
    );

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(DEPLOYER_ROLE, admin);
    }

    function deployToken(
        uint256 assetId,
        string calldata name,
        string calldata symbol,
        uint256 totalSupply,
        address assetOwner
    ) external onlyRole(DEPLOYER_ROLE) returns (address) {
        require(assetTokens[assetId] == address(0), "Token already deployed for asset");

        AssetToken token = new AssetToken(
            name,
            symbol,
            totalSupply,
            assetId,
            assetOwner,
            msg.sender
        );

        address tokenAddress = address(token);
        assetTokens[assetId] = tokenAddress;
        allTokens.push(tokenAddress);

        emit TokenDeployed(assetId, tokenAddress, name, symbol, totalSupply);
        return tokenAddress;
    }

    function getTokenAddress(uint256 assetId) external view returns (address) {
        return assetTokens[assetId];
    }
}

